  cg.addColorStop(0,'#7de9de00');cg.addColorStop(.22,band%2?'#d7a5ff45':'#65fff34a');cg.addColorStop(.7,band%2?'#95d5ff34':'#e8a8e83e');cg.addColorStop(1,'#b9eaff00');
