 for(let k=0;k<12;k++){const a=k*Math.PI/6;c.save();c.rotate(a);c.fillStyle=k%2?'#d5c4ec':'#b5ecf1';c.fillRect(-4,-128,8,31);c.restore()}c.restore();
 // Foreground low-frequency cloud banks: large masses, no repeated decorative boxes.
